target_TP53.json.body:
{"query": "
  query TargetAssociations($ensemblId: String!, $size: Int!) {
    target(ensemblId: $ensemblId) {
      id
      approvedSymbol
      approvedName
      tractability {
        label
        modality
        value
      }
    }
    associations: target(ensemblId: $ensemblId) {
      associatedDiseases(page: { size: $size, index: 0 }) {
        rows {
          disease { id name }
          score
          datatypeScores {
            id
            score
          }
        }
      }
    }
  }
", "variables": {"ensemblId": "ENSG00000141510", "size": 25}}

