safety_TP53.json.body:
{"query": "
  query TargetSafety($ensemblId: String!) {
    target(ensemblId: $ensemblId) {
      id
      approvedSymbol
      safetyLiabilities {
        event
        biosamples { tissueLabel }
        effects { direction }
        datasource
        literature
        url
      }
    }
  }
", "variables": {"ensemblId": "ENSG00000141510"}}

baseline_expression_TP53.json.body:
{"query": "
  query TargetBaselineExpression($ensemblId: String!, $size: Int!) {
    target(ensemblId: $ensemblId) {
      id
      approvedSymbol
      baselineExpression(page: { size: $size, index: 0 }) {
        count
        rows {
          unit
          median
          q1
          q3
          min
          max
          datasourceId
          targetId
          tissueBiosample { biosampleId biosampleName }
          tissueBiosampleParent { biosampleId biosampleName }
        }
      }
    }
  }
", "variables": {"ensemblId": "ENSG00000141510", "size": 3000}}
